# region: emit
def emit(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: render
def render(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(gather(sift(shape(emit(raw)))))

